import pathlib,json,html
R=pathlib.Path.cwd(); out=R/'output/evolution-30-journeys'; rows=json.loads((out/'journeys.json').read_text()); e=html.escape
deployment_path=out/'deployment.json'
deployment=json.loads(deployment_path.read_text()) if deployment_path.exists() else None
cards=[]
for x in rows:
 images=''.join('<a target="_blank" href="../evolution-static-100-2026-09-12/approved-selected-30-90-images/'+e(a['file'])+'">'+e(a['placement'])+'</a>' for a in x['images'])
 photo=next(a for a in x['images'] if a['placement']=='4x5')['file']; url='../plush-design-review/pages/'+x['slug']+'.html'
 cards.append(f'<article data-search="{e(x["id"]+" "+x["name"]+" "+x["journey"])}"><img loading="lazy" src="../evolution-static-100-2026-09-12/approved-selected-30-90-images/{e(photo)}" alt="{e(x["name"])}"><div><small>{e(x["id"])}</small><h2>{e(x["name"])}</h2><p class="journey">{e(x["journey"])}</p><h3>{e(x["settings"]["hero_prefix"]+" "+x["settings"]["hero_accent"]+" "+x["settings"]["hero_suffix"])}</h3><p>{e(x["settings"]["hero_body"])}</p><p class="sequence">Page order: {e(" → ".join(x["order"]))} → customer proof → FAQs → checkout invitation</p><div class="actions"><button data-page="{url}" data-title="{e(x["id"]+" · "+x["name"])}">Review page</button><a target="_blank" href="{url}">Open full page ↗</a><a target="_blank" href="https://zenkaiclothing.com/products/evolution-companions-complete-8-plush-collector-set?view={e(x["slug"])}">Live Shopify page ↗</a></div><nav aria-label="Ad sizes">Ad files: {images}</nav></div></article>')
text='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Evolutions · 30 ad-to-page journeys</title><style>*{box-sizing:border-box}body{margin:0;background:#f6f2ec;color:#30263b;font:16px/1.6 system-ui}header,main{max-width:1400px;margin:auto;padding:30px}h1{font-size:clamp(30px,4vw,54px);line-height:1.1}header p{max-width:850px}input{padding:14px;width:100%;max-width:650px;border:1px solid #cbbfcf;border-radius:12px;font:inherit}article{display:grid;grid-template-columns: minmax(240px,35%) 1fr;gap:28px;background:white;padding:24px;margin-bottom:24px;border-radius:20px;border:1px solid #e5dbe7}article>img{width:100%;border-radius:10px}h2{margin:0 0 16px}h3{font-size:24px;line-height:1.25}.journey{color:#70577d;font-weight:650}.sequence{font-size:14px;color:#655e68}.actions,nav{display:flex;gap:18px;align-items:center;flex-wrap:wrap}button{background:#493255;color:white;padding:12px 18px;border:0;border-radius:9px;cursor:pointer;font:inherit}a{color:#644378}nav{margin-top:18px}dialog{width:96vw;height:95vh;max-width:none;max-height:none;border:0;padding:0;background:#e6dfea;border-radius:14px}dialog::backdrop{background:#241b2bcc}.bar{display:flex;gap:10px;align-items:center;padding:10px;flex-wrap:wrap}.bar strong{margin-right:auto}iframe{display:block;height:calc(100% - 76px);width:100%;max-width:100%;border:0;margin:auto;background:white}article[hidden]{display:none}@media(max-width:700px){header,main{padding:18px}article{grid-template-columns:1fr;padding:18px}.bar strong{width:100%}iframe{height:calc(100% - 110px)}} </style></head><body><header><small>ZENKAI · EVOLUTIONS · REVIEW BEFORE LAUNCH</small><h1>30 ads.<br>30 matching journeys.</h1><p>Each page keeps the Rainbow Paws design and purchase components. The opening promise, sequence, supporting story and closing invitation follow the associated ad. Product photos remain the base template's proof; styled ad scenes are shown alongside for comparison.</p><p><strong>Local review:</strong> checkout is disabled in these previews. These pages have not been published and the new ads and $1,000 budget have not been activated.</p><input aria-label="Filter journeys" placeholder="Find a concept, ID, or emotion…" id="search"><p id="count">30 journeys</p></header><main>'''+''.join(cards)+'''</main><dialog><div class="bar"><strong id="title"></strong><button id="mobile">Mobile · 390</button><button id="desktop">Desktop</button><button id="close">Close</button></div><iframe title="Landing page preview"></iframe></dialog><script>const dialog=document.querySelector('dialog'),frame=document.querySelector('iframe');document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{frame.src=b.dataset.page;document.querySelector('#title').textContent=b.dataset.title;dialog.showModal()});document.querySelector('#close').onclick=()=>dialog.close();document.querySelector('#mobile').onclick=()=>frame.style.width='390px';document.querySelector('#desktop').onclick=()=>frame.style.width='100%';document.querySelector('#search').oninput=e=>{let n=0;document.querySelectorAll('article').forEach(a=>{a.hidden=!a.dataset.search.toLowerCase().includes(e.target.value.toLowerCase());if(!a.hidden)n++});document.querySelector('#count').textContent=n+' journeys'};</script></body></html>'''
if deployment and deployment.get('verified'):
 text=text.replace('REVIEW BEFORE LAUNCH','PUBLISHED JOURNEYS')
 text=text.replace('These pages have not been published and the new ads and $1,000 budget have not been activated.','All 30 Shopify pages are published. All 30 ads are enabled in the existing Evolutions ad set, with a $1,000 daily campaign budget and $55 cost cap. Use the live Shopify links to visit the published pages.')
(out/'index.html').write_text(text)
